function nearestExportValue(values, value) {
  return values.reduce((closest, candidate) =>
    Math.abs(candidate - value) <= Math.abs(closest - value) ? candidate : closest,
  );
}

function exportValueFromSliderIndex(values, index) {
  const safeIndex = Math.max(0, Math.min(values.length - 1, Math.round(index)));
  return values[safeIndex];
}

export function normalizeExportOuterPadding(outerPadding) {
  return nearestExportValue(EXPORT_OUTER_PADDING_VALUES, outerPadding);
}

export function exportOuterPaddingToSliderIndex(outerPadding) {
  return EXPORT_OUTER_PADDING_VALUES.indexOf(normalizeExportOuterPadding(outerPadding));
}

export function exportOuterPaddingFromSliderIndex(index) {
  return exportValueFromSliderIndex(EXPORT_OUTER_PADDING_VALUES, index);
}

export function normalizeExportInnerPadding(innerPadding) {
  return nearestExportValue(EXPORT_INNER_PADDING_VALUES, innerPadding);
}

export function exportInnerPaddingToSliderIndex(innerPadding) {
  return EXPORT_INNER_PADDING_VALUES.indexOf(normalizeExportInnerPadding(innerPadding));
}

export function exportInnerPaddingFromSliderIndex(index) {
  return exportValueFromSliderIndex(EXPORT_INNER_PADDING_VALUES, index);
}

export function normalizeExportCornerRadius(cornerRadius) {
  return nearestExportValue(EXPORT_CORNER_RADIUS_VALUES, cornerRadius);
}

export function exportCornerRadiusToSliderIndex(cornerRadius) {
  return EXPORT_CORNER_RADIUS_VALUES.indexOf(normalizeExportCornerRadius(cornerRadius));
}

export function exportCornerRadiusFromSliderIndex(index) {
  return exportValueFromSliderIndex(EXPORT_CORNER_RADIUS_VALUES, index);
}

export function normalizeExportFontSize(fontSize) {
  return nearestExportValue(EXPORT_FONT_SIZE_VALUES, fontSize);
}

// Line height and character advance are both measured at the 14px default, so
// a resized code font keeps the same optical rhythm by scaling them with it.
export function exportLineHeightForFontSize(fontSize) {
  return Math.round(normalizeExportFontSize(fontSize) * (EXPORT_LINE_HEIGHT / EXPORT_FONT_SIZE));
}

export function exportCharWidthForFontSize(fontSize) {
  return (EXPORT_CHAR_WIDTH / EXPORT_FONT_SIZE) * normalizeExportFontSize(fontSize);
}

